/* Brand fonts as TrueType (generated by scripts/woff-to-ttf.mjs into public/fonts).
   Used to embed vector text in PDFs and to give rasterised SVGs the real typefaces. */

export const FONT_FILES = {
  ui: 'InterTight-Regular.ttf',
  uiMd: 'InterTight-Medium.ttf',
  uiSb: 'InterTight-SemiBold.ttf',
  mono: 'IBMPlexMono-Regular.ttf',
  monoMd: 'IBMPlexMono-Medium.ttf',
} as const;

export type FontKey = keyof typeof FONT_FILES;

const cache = new Map<string, Promise<string>>();

function bufToBase64(buf: ArrayBuffer): string {
  const bytes = new Uint8Array(buf);
  let s = '';
  const chunk = 0x8000;
  for (let i = 0; i < bytes.length; i += chunk) s += String.fromCharCode(...bytes.subarray(i, i + chunk));
  return btoa(s);
}

export function fontBase64(file: string): Promise<string> {
  let p = cache.get(file);
  if (!p) {
    p = fetch(`${import.meta.env.BASE_URL}fonts/${file}`)
      .then((r) => {
        if (!r.ok) throw new Error(`Font ${file} not available`);
        return r.arrayBuffer();
      })
      .then(bufToBase64);
    cache.set(file, p);
    p.catch(() => cache.delete(file));
  }
  return p;
}

/** @font-face rules with embedded data, for SVGs that are rasterised (SVG images cannot load external fonts). */
export async function svgFontCss(): Promise<string> {
  const faces: [string, number, string][] = [
    ['Inter Tight', 400, FONT_FILES.ui],
    ['Inter Tight', 500, FONT_FILES.uiMd],
    ['Inter Tight', 600, FONT_FILES.uiSb],
    ['IBM Plex Mono', 400, FONT_FILES.mono],
    ['IBM Plex Mono', 500, FONT_FILES.monoMd],
  ];
  const rules = await Promise.all(
    faces.map(async ([family, weight, file]) => {
      try {
        const b64 = await fontBase64(file);
        return `@font-face{font-family:'${family}';font-weight:${weight};font-style:normal;src:url(data:font/ttf;base64,${b64}) format('truetype');}`;
      } catch {
        return '';
      }
    }),
  );
  return rules.join('');
}
